#!/bin/bash
set -eo pipefail
BASE=/data1/home/sunyiq/china_input_semantics_hpc_20261013_001
test ! -e "$BASE"
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_DEPLOY'
import base64, hashlib, io, json, os, pathlib, tarfile
base=pathlib.Path('/data1/home/sunyiq/china_input_semantics_hpc_20261013_001')
root=base/'execution_v1'
packed=base64.b64decode('', validate=True)
assert len(packed)==4541 and hashlib.sha256(packed).hexdigest()=='d1f4b1cb2dd5da4dbc1f916bb2f1b2d8e139ace92b5b15a7ce7f987b1b6b1a35'
expected=json.loads('{"hpc_probe.py":{"bytes":9159,"sha256":"41d163a1a82e2465e9890691c4867a87a13be5304d4bdb721a09dccc75829af3"},"probe.sbatch":{"bytes":910,"sha256":"4613b601212c2d93fe5b0c2c826f7208990b4f4f3f56e22420a9432857271380"},"PROBE_CONTRACT.json":{"bytes":3274,"sha256":"6d87f559f879deaa0f638931a333ac08ffc56dbee9c7d68a218d5bd4774d3f0f"}}')
assert len(packed)<65536 and not base.exists()
with tarfile.open(fileobj=io.BytesIO(packed), mode='r:gz') as archive:
    members=archive.getmembers()
    assert len(members)==3 and {m.name for m in members}==set(expected)
    contents={}
    for member in members:
        assert member.isfile() and member.name in expected and member.size<65536
        raw=archive.extractfile(member).read(65537)
        assert len(raw)==member.size==expected[member.name]['bytes']
        assert hashlib.sha256(raw).hexdigest()==expected[member.name]['sha256']
        contents[member.name]=raw
base.mkdir()
root.mkdir()
(root/'logs').mkdir()
for name,raw in contents.items():
    with (root/name).open('xb') as stream:
        stream.write(raw)
print('OWN_METADATA_DEPLOY_BYTES_VERIFIED', flush=True)
PY_DEPLOY
cd "$BASE/execution_v1"
set +e
submitted=$(sbatch probe.sbatch 2>&1)
code=$?
set -e
printf '%s\n' "$submitted"
printf 'OWN_METADATA_SUBMIT_EXIT=%s\n' "$code"
test "$code" = 0
[[ "$submitted" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]
job="${BASH_REMATCH[1]}"
test ! -e OWN_METADATA_JOB_ID
(set -o noclobber; printf '%s\n' "$job" > OWN_METADATA_JOB_ID)
printf 'OWN_METADATA_JOB_ID=%s\n' "$job"
printf 'OWN_METADATA_SUBMIT_DONE\n'
